            }
        }
        init
        {
            var v = value;
            Element e;
            switch (ElementTypeId)
            {
                case 1: e = Push(Ref<BoxEl>() with { RelativeTo = v }); break;
                case 2: e = Push(Ref<TextEl>() with { RelativeTo = v }); break;
                case 3: e = Push(Ref<ComponentEl>() with { RelativeTo = v }); break;
                case 5: e = Push(Ref<ScrollEl>() with { RelativeTo = v }); break;
                case 7: e = Push(Ref<ShowEl>() with { RelativeTo = v }); break;
                case 8: e = Push(Ref<ImageEl>() with { RelativeTo = v }); break;
                case 9: e = Push(Ref<GridEl>() with { RelativeTo = v }); break;
                case 11: e = Push(Ref<PolylineStrokeEl>() with { RelativeTo = v }); break;
                case 12: e = Push(Ref<SpanTextEl>() with { RelativeTo = v }); break;
                case 15: e = Push(Ref<IconLayerEl>() with { RelativeTo = v }); break;
                case 16: e = Push(Ref<PathEl>() with { RelativeTo = v }); break;
                case 17: e = Push(Ref<ListRowEl>() with { RelativeTo = v }); break;
                case 18: e = Push(Ref<SeriesEl>() with { RelativeTo = v }); break;
                case 19: e = Push(Ref<SpriteFieldEl>() with { RelativeTo = v }); break;
                default: e = Obj is HeapElement h ? new Element(h with { RelativeTo = v }) : this; break;
            }
            Obj = e.Obj; Id = e.Id; Epoch = e.Epoch;
        }
    }
}
